const menuToggleBtn = document.getElementById("menu-toggle-btn");
const navMenu = document.getElementById("nav-menu");
const themeToggleBtn = document.getElementById("theme-toggle-btn");
const projectListContainer = document.getElementById("project-list");
const projectModal = document.getElementById("project-modal");
const contactForm = document.getElementById("contact-form");
const formStatusMsg = document.getElementById("form-status-msg");

// Real projects with screenshots embedded directly as base64 images,
// so no separate image files are needed.
const projectsData = [
  {
    title: "MANAM",
    tag: "Restaurant Website",
    icon: "fa-solid fa-utensils",
    image: "data:image/png;base64,",
    description: "A restaurant landing page for a modern Filipino comfort food brand.",
    link: "https://rie755.github.io/manam-resto/"
  },
  {
    title: "Customer Feedback Form",
    tag: "PHP / MySQL",
    icon: "fa-solid fa-comment-dots",
    image: "data:image/png;base64,",
    description: "A customer feedback form for LutongBayan Restaurant, built with PHP and MySQL to collect and store diner reviews.",
    link: "https://rie755.github.io/survey-form/"
  },
  {
    title: "Alarie'''s Travel Diary",
    tag: "Travel Blog",
    icon: "fa-solid fa-plane",
    image: "data:image/png;base64,",
    description: "A personal travel diary website documenting trips, meals, and destinations worth revisiting, with stats on countries visited and cities explored.",
    link: "https://rie755.github.io/travel-webpage/"
  },
  {
    title: "BPI ATM Simulation",
    tag: "JavaScript",
    icon: "fa-solid fa-money-check-dollar",
    image: "data:image/png;base64,",
    description: "A simulated ATM banking system built with vanilla JavaScript, handling transactions like deposits, withdrawals, and balance checks.",
    link: "https://rie755.github.io/bpi-bank-system/"
  }
];

function toggleNavMenu() {
  navMenu.classList.toggle("show");
}

function toggleTheme() {
  document.body.classList.toggle("dark-mode");
  const isDark = document.body.classList.contains("dark-mode");
  themeToggleBtn.innerHTML = isDark
    ? '<i class="fa-solid fa-sun"></i>'
    : '<i class="fa-solid fa-moon"></i>';
}

function createProjectCard(project) {
  const card = document.createElement("div");
  card.className = "project-card";

  const thumb = project.image
    ? `<img src="${project.image}" alt="${project.title}" class="project-thumb" style="width:100%;height:190px;object-fit:cover;object-position:top center;">`
    : `<div class="project-thumb"><i class="${project.icon}"></i></div>`;

  card.innerHTML = `
    ${thumb}
    <div class="project-content">
      <span class="tag">${project.tag}</span>
      <h3>${project.title}</h3>
      <p>${project.description.substring(0, 90)}...</p>
      <button>View Details</button>
    </div>
  `;

  card.querySelector("button").addEventListener("click", () => openProjectModal(project));
  return card;
}

function renderProjectCards() {
  projectsData.forEach((project) => {
    projectListContainer.appendChild(createProjectCard(project));
  });
}

function openProjectModal(project) {
  const modalImage = document.getElementById("modal-image");
  if (project.image) {
    modalImage.src = project.image;
    modalImage.style.display = "block";
  } else {
    modalImage.style.display = "none";
  }
  document.getElementById("modal-title").textContent = project.title;
  document.getElementById("modal-description").textContent = project.description;
  document.getElementById("modal-link").href = project.link;
  projectModal.classList.add("show-modal");
}

function closeProjectModal() {
  projectModal.classList.remove("show-modal");
}

function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function showFormError(message) {
  formStatusMsg.textContent = message;
  formStatusMsg.classList.remove("success");
  formStatusMsg.classList.add("error");
}

function showFormSuccess(message) {
  formStatusMsg.textContent = message;
  formStatusMsg.classList.remove("error");
  formStatusMsg.classList.add("success");
}

function handleContactFormSubmit(event) {
  event.preventDefault();

  const name = document.getElementById("name-input").value.trim();
  const email = document.getElementById("email-input").value.trim();
  const message = document.getElementById("message-input").value.trim();

  if (!name || !email || !message) {
    showFormError("Please complete all fields.");
    return;
  }

  if (!isValidEmail(email)) {
    showFormError("Please enter a valid email address.");
    return;
  }

  showFormSuccess("Message sent successfully!");
  contactForm.reset();
}

menuToggleBtn.addEventListener("click", toggleNavMenu);
themeToggleBtn.addEventListener("click", toggleTheme);
contactForm.addEventListener("submit", handleContactFormSubmit);
document.querySelector(".close-btn").addEventListener("click", closeProjectModal);

window.addEventListener("click", (event) => {
  if (event.target === projectModal) {
    closeProjectModal();
  }
});

renderProjectCards();
